{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Isotretinoin, the closest retinoid acid analog, has a systemic bioavailability of 40% at 1 mg/kg/day, supporting F ≥ 20% for the retinoid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Tretinoin oral bioavailability is approximately 50% after a single dose, supporting high oral bioavailability for retinoid derivatives.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Acitretin absolute bioavailability is approximately 60% (range 36–95%) after oral dosing, supporting high F for retinoid-type molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Etretinate absolute bioavailability is about 40% after oral capsule administration, supporting high F for lipophilic retinoid analogs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Paracetamol, which shares the p-hydroxyanilide substructure, has an absolute oral bioavailability of 63%, supporting efficient absorption of the amide-containing moiety.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "13-cis-retinoic acid is reported to have low absolute bioavailability due to gut degradation, a contradictory consideration for the retinoid acid scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a retinoid p-hydroxyanilide. Multiple close retinoid analogs (isotretinoin, tretinoin, acitretin, etretinate) show oral bioavailability of 40–60%, and the paracetamol-like amide substructure is well absorbed. Although some retinoid acid formulations are low/erratic, the weight of evidence supports F ≥ 20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability data for the exact retinoid amide query molecule.",
    "Potential first-pass hydrolysis to retinoic acid and p-aminophenol is not directly characterized.",
    "Formulation and food effects on the amide's absorption are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

